import{_ as t,o as a,c as i,a0 as o}from"./chunks/framework.C0WKPwzJ.js";const p=JSON.parse('{"title":"What is Autodevelop","description":"A Cursor plugin that turns requests into GitHub Project tickets, keeps an audit trail, and sends allowlisted stakeholder mail only after an explicit confirm.","frontmatter":{"title":"What is Autodevelop","description":"A Cursor plugin that turns requests into GitHub Project tickets, keeps an audit trail, and sends allowlisted stakeholder mail only after an explicit confirm."},"headers":[],"relativePath":"overview.md","filePath":"overview.md","lastUpdated":1788171427000}'),r={name:"overview.md"};function l(n,e,s,d,c,u){return a(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="what-is-autodevelop" tabindex="-1">What is Autodevelop <a class="header-anchor" href="#what-is-autodevelop" aria-label="Permalink to &quot;What is Autodevelop&quot;">​</a></h1><p>Copyright (c) 2026 Devrecated.</p><p>Autodevelop turns an AI coding tool into a project-management and communication layer. Work is planned, executed, verified, and reported without leaving the editor.</p><h2 id="what-you-get" tabindex="-1">What you get <a class="header-anchor" href="#what-you-get" aria-label="Permalink to &quot;What you get&quot;">​</a></h2><ul><li><strong>Tickets are the source of truth.</strong> Chat, notes, or the ticket UI become GitHub Project issues with acceptance criteria. Product work does not ship without a ticket.</li><li><strong>An audit trail.</strong> Claim, progress, verification, pull requests, and stakeholder email write back to the ticket.</li><li><strong>Confirmed stakeholder mail.</strong> Email is written only after an explicit confirmation, and only to allowlisted recipients.</li><li><strong>Ship gates.</strong> Staging and production deploys wait for an exact phrase in that conversation.</li><li><strong>Hosted surfaces.</strong> Invited members file tickets. Operators connect GitHub and manage the organization. Owners review work and delivery.</li></ul><h2 id="how-a-request-flows" tabindex="-1">How a request flows <a class="header-anchor" href="#how-a-request-flows" aria-label="Permalink to &quot;How a request flows&quot;">​</a></h2><ol><li>Someone files a request in chat, from notes, or in the ticket UI.</li><li>Autodevelop opens a GitHub Project ticket with acceptance criteria.</li><li>A developer claims the ticket in Cursor and implements the work.</li><li>Progress and verification stay on the ticket.</li><li>A pull request and optional preview follow.</li><li>Stakeholder mail goes out only after the human confirms the draft.</li></ol><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><a href="./guide">Client guide</a></li><li><a href="./install">Install</a></li><li><a href="./cli">CLI</a></li><li><a href="./github">GitHub App</a></li></ul>',9)])])}const f=t(r,[["render",l]]);export{p as __pageData,f as default};
